<template>
    <div class="game-rules" :class="{ popout: isDesktop }">
        <div v-for="block in strings.gameRules.blocks" v-bind:key="block.title">
            <h2 class="section-header">{{ block.title }}</h2>
            <div class="content-block">
                <template v-for="(item, index) in block.content">
                    <span v-if="checkSkin(item)" v-bind:key="index"></span>
                    <p v-else-if="item.type === 'text'" v-bind:style="item.style" v-bind:key="index">{{ item.value }}</p>
                    <h3 v-else-if="item.type === 'title'" v-bind:style="item.style" v-bind:key="index">{{ item.value }}</h3>
                    <img v-else-if="item.type === 'image'" v-bind:style="item.style" v-bind:key="index" :src="getImagePath(item.value)" />
                </template>
            </div>
        </div>
    </div>
</template>

<style src="./game-rules.less" lang="less" scoped></style>
<script src="./game-rules.ts" lang="ts"></script>